const CATS=["Food","Transport","Shopping","Bills","Health","Fun","Other"],ICATS=["Salary","Freelance","Gift","Other"];
const COL=["#1b7a4b","#12264f","#c97b00","#b3261e","#6a4fb3","#0f8ea3","#8a94a8"];
const CUR=["USD","EUR","GBP","INR","AUD","CAD","JPY"];
const NAVS=[["dash","Dashboard"],["add","Add"],["hist","History"],["bud","Budget"],["rec","Recurring"],["bank","Banks"],["rep","Reports"],["cloud","Backup"],["set","Settings"]];
let S,view="dash",editId=null,addType="expense",f={q:"",m:"",c:""},repM="",splash=true;
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const init=()=>({user:null,in:false,cur:"USD",bal:0,income:0,budget:0,tx:[],rec:[],theme:"dark",notify:true,hide:false,cloud:false,cloudAt:"",notes:[],banks:[]});
try{S=JSON.parse(localStorage.getItem("sw1"))||init()}catch(e){S=init()}
S={...init(),...S};
const save=()=>{try{localStorage.setItem("sw1",JSON.stringify(S))}catch(e){}};
const today=()=>new Date().toISOString().slice(0,10);
const mk=d=>d.slice(0,7);
const fmt=n=>{try{return new Intl.NumberFormat(undefined,{style:"currency",currency:S.cur}).format(n)}catch(e){return n.toFixed(2)}};
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,6);
function toast(m,bad){const t=$("#t");t.innerHTML=`<div class="toast ${bad?"bad":""}">${esc(m)}</div>`;setTimeout(()=>t.innerHTML="",3200)}
function stats(m){let inc=0,exp=0,by={};S.tx.forEach(x=>{if(mk(x.date)!==m)return;if(x.type==="income")inc+=x.amt;else{exp+=x.amt;by[x.cat]=(by[x.cat]||0)+x.amt}});return{inc,exp,by}}
const balance=()=>S.tx.reduce((b,x)=>b+(x.type==="income"?x.amt:-x.amt),+S.bal||0);
function addPeriod(d,fr){const x=new Date(d+"T00:00:00");if(fr==="daily")x.setDate(x.getDate()+1);else if(fr==="weekly")x.setDate(x.getDate()+7);else x.setMonth(x.getMonth()+1);return x.toISOString().slice(0,10)}
function processRec(){let n=0;S.rec.forEach(r=>{let g=0;while(r.next<=today()&&g++<400){S.tx.push({id:uid(),type:"expense",amt:r.amt,cat:r.cat,date:r.next,note:(r.note||"Recurring")+" (auto)"});r.next=addPeriod(r.next,r.freq);n++}});if(n){notify(n+" recurring expense"+(n>1?"s were":" was")+" added automatically");save();setTimeout(()=>toast(n+" recurring expense"+(n>1?"s":"")+" added"),300)}}
function apply(){const r=document.documentElement;S.theme==="auto"?r.removeAttribute("data-theme"):r.setAttribute("data-theme",S.theme);document.body.classList.toggle("hide",!!S.hide)}
function go(v){view=v;if(v!=="add")editId=null;render()}
function render(){apply();const a=$("#app");if(splash){a.innerHTML=`<div class="splash"><img src="data:image/jpeg;base64," alt=""><div class="logo">Spend<b>Wise</b></div><p>Smart Expense Tracker</p></div>`;return}if(!S.user||!S.in){a.innerHTML=login();return}
a.innerHTML=`<header><div class="logo"><img src="data:image/jpeg;base64," alt="">Spend<b>Wise</b></div><button class="link" onclick="go('notes')" aria-label="Notifications">🔔${unread()?` <b>${unread()}</b>`:""}</button></header>
<nav>${NAVS.map(n=>`<button class="${view===n[0]?"on":""}" onclick="go('${n[0]}')">${n[1]}</button>`).join("")}</nav>${({dash,add,hist,bud,rec,bank,rep,cloud,set,notes})[view]()}`}
/* Login & profile setup */
function login(){const u=S.user;return `<div class="login card"><div style="text-align:center"><img src="data:image/jpeg;base64," alt="" style="width:96px;border-radius:50%"><div class="logo" style="margin-top:6px">Spend<b>Wise</b></div></div><p style="color:var(--mu);margin:0 0 6px">Smart expense tracker. Your data stays in this browser.</p>
${u?`<h2 style="margin-top:14px">Welcome back, ${esc(u.name)}</h2><label>Password</label><input id="pw" type="password" autocomplete="current-password"><button class="btn" onclick="signin()">Sign in</button> <button class="link" onclick="if(!window._c){window._c=1;toast('Tap again to erase all data and start over',1);return}S=init();save();window._c=0;render()">Start over</button>`:
`<h2 style="margin-top:14px">Create your profile</h2>
<label>Name</label><input id="n" autocomplete="name">
<label>Email</label><input id="e" type="email" autocomplete="email"><label>Password (6+ characters)</label><input id="pw" type="password" autocomplete="new-password">
<button class="btn" onclick="signup()">Start tracking</button>`}</div>`}
async function signup(){const n=$("#n").value.trim(),e=$("#e").value.trim(),p=$("#pw").value;if(!n||!/\S+@\S+\.\S+/.test(e))return toast("Enter your name and a valid email",1);
if(p.length<6)return toast("Password needs 6+ characters",1);S.user={name:n,email:e,h:await hash(p)};S.in=true;save();render()}
/* Dashboard */
function budgetBlock(exp){if(!S.budget)return `<p class="empty">No monthly budget yet. <button class="link" onclick="go('bud')">Set one</button></p>`;
const p=exp/S.budget,cl=p>1?"bad":p>=.8?"warn":"",msg=p>1?`Budget crossed by ${fmt(exp-S.budget)}`:p>=.8?"Nearing your budget":"On track";
return `<div class="bar ${cl}"><i style="width:${Math.min(100,p*100)}%"></i></div><b>${msg}</b> <span style="color:var(--mu)">${fmt(exp)} of ${fmt(S.budget)} (${Math.round(p*100)}%)</span>`}
function txRow(x,acts){return `<div class="tx"><div><b>${esc(x.cat)}</b> ${x.note?"· "+esc(x.note):""}<small>${x.date}</small></div><div class="acts"><b class="${x.type==="income"?"inc":"exp"}">${x.type==="income"?"+":"−"}${fmt(x.amt)}</b>${acts?`<button class="link" onclick="edit('${x.id}')">Edit</button><button class="link" onclick="del('${x.id}')">Delete</button>`:""}</div></div>`}
function catBars(by){const t=Object.values(by).reduce((a,b)=>a+b,0);if(!t)return `<p class="empty">No expenses this month yet.</p>`;
return Object.entries(by).sort((a,b)=>b[1]-a[1]).map(([c,v])=>`<div style="margin:8px 0"><div style="display:flex;justify-content:space-between"><span>${esc(c)}</span><span>${fmt(v)}</span></div><div class="bar" style="margin:3px 0"><i style="width:${v/t*100}%;background:var(--pri)"></i></div></div>`).join("")}
function dash(){const m=mk(today()),s=stats(m),tot=t=>S.tx.filter(x=>x.type===t).reduce((a,x)=>a+x.amt,0),recent=[...S.tx].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);
return `<div class="card"><span style="color:var(--mu)">Current balance</span><span class="num big">${fmt(balance())}</span><span style="color:var(--mu);font-size:13px">Total income ${fmt(tot("income"))} · Total expenses ${fmt(tot("expense"))}</span></div>
<div class="grid"><div class="stat"><span>Income this month</span><span class="num inc">${fmt(s.inc)}</span></div><div class="stat"><span>Expenses this month</span><span class="num exp">${fmt(s.exp)}</span></div></div>
<div class="card"><h2>Budget status</h2>${budgetBlock(s.exp)}</div>
<div class="card"><h2>Spending by category</h2>${catBars(s.by)}</div>
<div class="card"><h2>Recent transactions</h2>${recent.length?recent.map(x=>txRow(x)).join(""):`<p class="empty">Nothing yet. <button class="link" onclick="go('add')">Add your first transaction</button></p>`}</div>`}
/* Add / edit */
function add(){const e=editId?S.tx.find(x=>x.id===editId):null,t=e?e.type:addType,cs=t==="income"?ICATS:CATS;
return `<div class="card"><h2>${e?"Edit transaction":"Add transaction"}</h2>${e?"":`<div class="row"><button class="btn ${t==="income"?"":"alt"}" onclick="addType='income';render()">Income</button><button class="btn ${t==="expense"?"":"alt"}" onclick="addType='expense';render()">Expense</button></div>`}
<label>Amount</label><input id="a" type="number" step="0.01" min="0" value="${e?e.amt:""}">
<label>Category</label><select id="k">${cs.map(c=>`<option ${e&&e.cat===c?"selected":""}>${c}</option>`).join("")}</select>
<label>Date</label><input id="d" type="date" value="${e?e.date:today()}">
<label>Note</label><input id="o" value="${e?esc(e.note):""}" placeholder="Optional">
<button class="btn" onclick="saveTx('${t}')">${e?"Save changes":"Save "+t}</button></div>`}
function saveTx(t){const amt=+$("#a").value,d=$("#d").value;if(!(amt>0)||!d)return toast("Enter an amount above 0 and a date",1);
const o={type:t,amt,cat:$("#k").value,date:d,note:$("#o").value.trim()};
if(editId){Object.assign(S.tx.find(x=>x.id===editId),o);editId=null}else S.tx.push({id:uid(),...o});save();
let bad=0;if(t==="expense"&&S.budget){const e2=stats(mk(d)).exp;if(e2>S.budget){bad=1;notify("Warning: budget crossed for "+mk(d)+" ("+fmt(e2)+" of "+fmt(S.budget)+")","bad")}else if(e2>=S.budget*.8)notify("Reminder: you have used "+Math.round(e2/S.budget*100)+"% of your monthly budget","warn");save()}
view="dash";render();bad?toast("Budget limit exceeded for "+mk(d),1):toast("Saved")}
function edit(id){editId=id;view="add";render()}
function del(id){S.tx=S.tx.filter(x=>x.id!==id);save();render();toast("Transaction deleted")}
/* History */
function hist(){let l=[...S.tx].sort((a,b)=>b.date.localeCompare(a.date));
if(f.q)l=l.filter(x=>(x.note+x.cat).toLowerCase().includes(f.q.toLowerCase()));if(f.m)l=l.filter(x=>mk(x.date)===f.m);if(f.c)l=l.filter(x=>x.cat===f.c);
return `<div class="card"><h2>Transaction history</h2><div class="row"><input placeholder="Search" value="${esc(f.q)}" oninput="f.q=this.value;list()"><input type="month" value="${f.m}" onchange="f.m=this.value;list()"><select onchange="f.c=this.value;list()"><option value="">All categories</option>${[...new Set([...CATS,...ICATS])].map(c=>`<option ${f.c===c?"selected":""}>${c}</option>`).join("")}</select></div><div id="hl">${hl(l)}</div></div>`}
const hl=l=>l.length?l.map(x=>txRow(x,1)).join(""):`<p class="empty">No transactions match.</p>`;
function list(){let l=[...S.tx].sort((a,b)=>b.date.localeCompare(a.date));if(f.q)l=l.filter(x=>(x.note+x.cat).toLowerCase().includes(f.q.toLowerCase()));if(f.m)l=l.filter(x=>mk(x.date)===f.m);if(f.c)l=l.filter(x=>x.cat===f.c);$("#hl").innerHTML=hl(l)}
/* Budget */
function bud(){const s=stats(mk(today()));return `<div class="card"><h2>Monthly budget</h2><label>Budget amount (${S.cur})</label><input id="g" type="number" min="0" step="0.01" value="${S.budget||""}"><button class="btn" onclick="S.budget=+$('#g').value||0;save();render();toast('Budget saved')">Save budget</button></div><div class="card"><h2>This month</h2>${budgetBlock(s.exp)}</div>`}
/* Recurring */
function rec(){return `<div class="card"><h2>New recurring expense</h2><div class="row"><div><label>Amount</label><input id="ra" type="number" min="0" step="0.01"></div><div><label>Category</label><select id="rk">${CATS.map(c=>`<option>${c}</option>`).join("")}</select></div></div>
<div class="row"><div><label>Frequency</label><select id="rf"><option value="daily">Daily</option><option value="weekly">Weekly</option><option value="monthly" selected>Monthly</option></select></div><div><label>First date</label><input id="rd" type="date" value="${today()}"></div></div>
<label>Note</label><input id="rn" placeholder="e.g. Rent"><button class="btn" onclick="addRec()">Save recurring expense</button></div>
<div class="card"><h2>Active</h2>${S.rec.length?S.rec.map(r=>`<div class="tx"><div><b>${esc(r.cat)}</b> ${r.note?"· "+esc(r.note):""}<small>${r.freq}, next ${r.next}</small></div><div class="acts"><b class="exp">${fmt(r.amt)}</b><button class="link" onclick="S.rec=S.rec.filter(x=>x.id!=='${r.id}');save();render()">Remove</button></div></div>`).join(""):`<p class="empty">No recurring expenses. Due ones are added automatically when you open the app.</p>`}</div>`}
function addRec(){const a=+$("#ra").value,d=$("#rd").value;if(!(a>0)||!d)return toast("Enter an amount above 0 and a start date",1);
S.rec.push({id:uid(),amt:a,cat:$("#rk").value,freq:$("#rf").value,next:d,note:$("#rn").value.trim()});notify("Reminder saved: "+$("#rk").value+" ("+$("#rf").value+")");processRec();save();render();toast("Recurring expense saved")}
/* Reports */
function rep(){const m=repM||mk(today()),s=stats(m);let acc=0;const en=Object.entries(s.by).sort((a,b)=>b[1]-a[1]);
const grad=en.map(([c,v],i)=>{const a=acc/s.exp*100;acc+=v;return `${COL[i%7]} ${a}% ${acc/s.exp*100}%`}).join(",");
const months=[];for(let i=5;i>=0;i--){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i);months.push(d.toISOString().slice(0,7))}
const data=months.map(k=>({k,...stats(k)})),mx=Math.max(1,...data.map(x=>Math.max(x.inc,x.exp)));
return `<div class="card"><h2>Monthly report</h2><input type="month" value="${m}" onchange="repM=this.value;render()">
<div class="grid" style="margin:12px 0 0"><div class="stat"><span>Income</span><span class="num inc">${fmt(s.inc)}</span></div><div class="stat"><span>Expenses</span><span class="num exp">${fmt(s.exp)}</span></div><div class="stat"><span>Saved</span><span class="num">${fmt(s.inc-s.exp)}</span></div></div></div>
<div class="card"><h2>Expenses by category</h2>${s.exp?`<div class="row" style="align-items:center;flex-wrap:wrap"><div class="pie" style="background:conic-gradient(${grad})"></div><div class="legend">${en.map(([c,v],i)=>`<div><span><i style="background:${COL[i%7]}"></i>${esc(c)}</span><span>${fmt(v)}</span></div>`).join("")}</div></div>`:`<p class="empty">No expenses in this month.</p>`}</div>
<div class="card"><h2>Last 6 months</h2><div class="cols">${data.map(x=>`<div class="col"><div><i style="height:${x.inc/mx*100}%;background:var(--ok)" title="Income"></i><i style="height:${x.exp/mx*100}%;background:var(--bad)" title="Expenses"></i></div>${x.k.slice(2)}</div>`).join("")}</div><p style="color:var(--mu);font-size:13px;margin:8px 0 0"><span class="inc">■</span> Income <span class="exp">■</span> Expenses</p></div>
<button class="btn noprint" onclick="window.print()">Export PDF</button> <button class="btn alt noprint" onclick="shareRep('${m}')">Share report</button>`}
/* Settings */
function set(){return `<div class="card"><h2>Profile</h2><label>Name</label><input id="sn" value="${esc(S.user.name)}">
<div class="row"><div><label>Currency</label><select id="sc">${CUR.map(c=>`<option ${S.cur===c?"selected":""}>${c}</option>`).join("")}</select></div><div><label>Theme</label><select id="st">${["auto","light","dark"].map(c=>`<option ${S.theme===c?"selected":""}>${c}</option>`).join("")}</select></div></div>
<button class="btn" onclick="S.user.name=$('#sn').value.trim()||S.user.name;S.cur=$('#sc').value;S.theme=$('#st').value;save();render();toast('Settings saved')">Save settings</button></div>
<div class="card"><h2>Notifications and privacy</h2><label class="sw"><input type="checkbox" ${S.notify?"checked":""} onchange="S.notify=this.checked;save()"> Budget and recurring alerts</label><label class="sw"><input type="checkbox" ${S.hide?"checked":""} onchange="S.hide=this.checked;save();apply()"> Hide amounts on screen</label><button class="btn alt" onclick="eraseAll()">Erase all data</button></div><div class="card"><h2>Session</h2><button class="btn alt" onclick="S.in=false;view='dash';save();render()">Log out</button></div>`}
const hash=async p=>{try{const b=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(p));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join("")}catch(e){return btoa(unescape(encodeURIComponent(p)))}};
async function signin(){if(S.user.h&&await hash($("#pw").value)!==S.user.h)return toast("Wrong password",1);S.in=true;save();render()}
const unread=()=>S.notes.filter(n=>!n.r).length;
function notify(m,t){if(!S.notify)return;S.notes.unshift({id:uid(),m,t:t||"info",d:new Date().toISOString().slice(0,16).replace("T"," "),r:0});S.notes=S.notes.slice(0,50)}
function notes(){const l=S.notes;l.forEach(n=>n.r=1);save();return `<div class="card"><h2>Notifications</h2>${l.length?l.map(n=>`<div class="tx"><div class="${n.t==="bad"?"exp":""}">${esc(n.m)}<small>${n.d}</small></div></div>`).join(""):`<p class="empty">No notifications yet.</p>`}${l.length?`<button class="link" onclick="S.notes=[];save();render()">Clear all</button>`:""}</div>`}
function eraseAll(){if(!window._e){window._e=1;return toast("Tap again to erase everything",1)}S=init();save();window._e=0;render()}
function shareRep(m){const s=stats(m),t="SpendWise report "+m+"\nIncome: "+fmt(s.inc)+"\nExpenses: "+fmt(s.exp)+"\nSaved: "+fmt(s.inc-s.exp);if(navigator.share)navigator.share({title:"SpendWise report",text:t}).catch(()=>{});else{try{navigator.clipboard.writeText(t);toast("Report copied to clipboard")}catch(e){toast("Sharing is not available here",1)}}}
/* Bank accounts and sync (demo: no real bank is contacted) */
function bank(){return `<div class="card"><h2>Link a bank account</h2><div class="row"><div><label>Bank name</label><input id="bn"></div><div><label>Last 4 digits</label><input id="bl" maxlength="4" inputmode="numeric"></div></div><label>Verification code (OTP)</label><input id="bo" maxlength="6" inputmode="numeric" placeholder="Any 6 digits in this demo"><button class="btn" onclick="addBank()">Link account</button><p class="empty">Demo mode. Real bank sync needs a provider such as Plaid and a backend.</p></div>
<div class="card"><h2>Linked accounts</h2>${S.banks.length?S.banks.map(b=>{const t=S.tx.filter(x=>x.bank===b.id);return `<div class="tx"><div><b>${esc(b.name)} ••${esc(b.l4)}</b>${b.def?" · default":""}<small>${t.length} synced transactions</small></div><div class="acts"><button class="link" onclick="syncBank('${b.id}')">Sync</button><button class="link" onclick="defBank('${b.id}')">Default</button><button class="link" onclick="rmBank('${b.id}')">Remove</button></div></div>`}).join(""):`<p class="empty">No accounts linked.</p>`}</div>`}
function addBank(){const n=$("#bn").value.trim(),l=$("#bl").value.trim();if(!n||!/^\d{4}$/.test(l)||!/^\d{6}$/.test($("#bo").value))return toast("Enter a bank name, 4 digits and a 6-digit code",1);S.banks.push({id:uid(),name:n,l4:l,def:!S.banks.length});save();render();toast("Account linked")}
function syncBank(id){const b=S.banks.find(x=>x.id===id),s=[["Food","Grocery"],["Transport","Fuel"],["Bills","Utility bill"],["Fun","Streaming"],["Shopping","Online order"]];
for(let i=0;i<3;i++){const p=s[Math.floor(Math.random()*5)];S.tx.push({id:uid(),type:"expense",amt:Math.round((5+Math.random()*75)*100)/100,cat:p[0],date:today(),note:p[1]+" (bank sync demo)",bank:id})}
notify("Bank sync: 3 transactions added from "+b.name);save();render();toast("Synced 3 demo transactions")}
function defBank(id){S.banks.forEach(b=>b.def=b.id===id);save();render()}
function rmBank(id){S.banks=S.banks.filter(b=>b.id!==id);if(S.banks.length&&!S.banks.some(b=>b.def))S.banks[0].def=true;save();render()}
/* Cloud backup */
function cloud(){return `<div class="card"><h2>Cloud backup</h2><label class="sw"><input type="checkbox" ${S.cloud?"checked":""} onchange="S.cloud=this.checked;save();render()"> Cloud sync enabled</label>${S.cloud?`<p>${S.cloudAt?"Last backup: "+esc(S.cloudAt):"No backup yet."}</p><button class="btn" onclick="backup()">Upload data securely</button><p class="empty">Demo: the copy stays in this browser until a real server is added.</p>`:`<p class="empty">Local storage only. Your data stays in this browser.</p>`}</div>
<div class="card"><h2>Move data between devices</h2><button class="btn" onclick="exportData()">Download backup file</button> <button class="btn alt" onclick="$('#fi').click()">Restore from file</button><input id="fi" type="file" accept=".json" hidden onchange="importData(this.files[0])"></div>`}
function backup(){S.cloudAt=new Date().toLocaleString();try{localStorage.setItem("sw1_cloud",JSON.stringify({...S,notes:[]}))}catch(e){}save();render();toast("Backup complete and synced")}
function exportData(){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([JSON.stringify(S)],{type:"application/json"}));a.download="spendwise-backup.json";a.click()}
function importData(f){if(!f)return;const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);if(!d.user||!Array.isArray(d.tx))throw 0;S={...init(),...d};save();render();toast("Data restored")}catch(e){toast("That file is not a SpendWise backup",1)}};r.readAsText(f)}
apply();processRec();render();setTimeout(()=>{splash=false;render()},1500);
